enum Event: Decodable {                       // the sum type replaces the class hierarchy
    case orderCreated(OrderCreated)
    case orderCancelled(OrderCancelled)

    private enum Keys: String, CodingKey { case type }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: Keys.self)
        switch try c.decode(String.self, forKey: .type) {   // the tag decides the case
        case "order-created":   self = .orderCreated(try OrderCreated(from: decoder))
        case "order-cancelled": self = .orderCancelled(try OrderCancelled(from: decoder))
        default: throw DecodingError.dataCorruptedError(forKey: .type, in: c,
                                                        debugDescription: "unknown type")
        }
    }
}
